(()=>{'use strict';let current=null;const $=id=>document.getElementById(id),bound=new WeakMap();
function sync(){const el=current?.el,valid=el?.isConnected;for(const button of $('layoutPanel').querySelectorAll('button[data-move],button[data-order],#resetPosition'))button.disabled=!valid;
 $('selectedPositionLabel').textContent=valid?(el.tagName==='IMG'?'تصویر انتخاب‌شده':el.textContent.trim().slice(0,65)):'«انتخاب برای جابه‌جایی» را روشن کنید و روی متن یا عکس بزنید.';
 if(!valid)return;const siblings=[...el.parentElement.children].filter(x=>x.dataset.siteLayout),index=siblings.indexOf(el);$('moveEarlier').disabled=index<=0;$('moveLater').disabled=index<0||index===siblings.length-1;
}
function entries(){current.config.layout ||= {};return current.config.layout[current.path] ||= {};}
function refresh(){window.PBSiteLayout.apply(current.doc,current.config,current.path);current.mark();sync();}
for(const button of document.querySelectorAll('[data-move]'))button.onclick=()=>{if(!current?.el.isConnected)return;const [prop,amount]=button.dataset.move.split(':'),all=entries(),key=current.el.dataset.siteLayout,v=all[key] ||= {};v[prop]=Math.max(-48,Math.min(48,(v[prop]||0)+Number(amount)));refresh();};
for(const button of document.querySelectorAll('[data-order]'))button.onclick=()=>{if(!current?.el.isConnected)return;const el=current.el,siblings=[...el.parentElement.children].filter(x=>x.dataset.siteLayout),i=siblings.indexOf(el),j=i+Number(button.dataset.order);if(i<0||j<0||j>=siblings.length)return;[siblings[i],siblings[j]]=[siblings[j],siblings[i]];const all=entries();siblings.forEach((node,rank)=>{const key=node.dataset.siteLayout;all[key]={...all[key],rank};});refresh();};
$('resetPosition').onclick=()=>{if(!current?.el.isConnected)return;const all=entries();for(const el of current.el.parentElement.children){const key=el.dataset.siteLayout;if(all[key])delete all[key].rank;}delete all[current.el.dataset.siteLayout];refresh();};
window.PBSiteLayoutEditor={install(doc,config,mark){if(current&&current.doc!==doc){current=null;sync();}const path=JSON.parse(doc.getElementById('site-layout-data')?.textContent||'{"pathname":"/"}').pathname;window.PBSiteLayout.apply(doc,config,path);let binding=bound.get(doc);if(!binding){binding={doc,config,mark,path};bound.set(doc,binding);doc.addEventListener('click',event=>{if(!$('positionMode').checked)return;const el=event.target.closest('[data-site-layout]');if(!el)return;event.preventDefault();event.stopImmediatePropagation();doc.querySelectorAll('.site-selected-position').forEach(x=>x.classList.remove('site-selected-position'));el.classList.add('site-selected-position');current={...binding,el};sync();},true);const style=doc.createElement('style');style.textContent='.site-selected-position{outline:2px dashed #315efb!important;outline-offset:4px}';doc.head.append(style);}Object.assign(binding,{config,mark,path});if(current?.doc===doc){Object.assign(current,{config,mark,path});sync();}}};sync();
})();
